CREATE TABLE IF NOT EXISTS mandates (agent_id text PRIMARY KEY, agent_wallet text NOT NULL, owner text NOT NULL, per_tx_limit bigint NOT NULL, daily_limit bigint NOT NULL, active boolean NOT NULL DEFAULT true, starts_at timestamptz NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS authorizations (verdict_id uuid PRIMARY KEY, request_id uuid UNIQUE NOT NULL, agent_id text NOT NULL, buyer_wallet text NOT NULL, recipient text NOT NULL, amount_base_units numeric NOT NULL, mint text NOT NULL, network text NOT NULL, resource_id text NOT NULL, decision text NOT NULL, reason_code text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (idempotency_key text PRIMARY KEY, kind text NOT NULL, signature text, status text NOT NULL, amount_base_units numeric, network text, raw_receipt jsonb, updated_at timestamptz NOT NULL DEFAULT now());
